import { Easing, Interactive, Sequence, interpolate, useCurrentFrame, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";

interface GradientScaleCutTextProps {
  text?: string;
  giantFontSize?: number;
  compactFontSize?: number;
  fontWeight?: number;
  gradientStart?: string;
  gradientEnd?: string;
  ghostColor?: string;
  backgroundColor?: string;
  anchorOffsetX?: number;
  giantTravel?: number;
  settleTravel?: number;
  cutFrame?: number;
  revealSoftness?: number;
  compactBlur?: number;
  speed?: number;
  className?: string;
}

const gradientScaleCutTextLength = 36;

const REVEAL_END = 33;
const SETTLE_FRAMES = 8;
const GIANT_Y = -28;
const GIANT_X_CORRECTION = -48;
const COMPACT_Y = 5;
const COMPACT_X_SCALE = 0.87;
const COMPACT_MID_X = 24;
const COMPACT_START_X_CORRECTION = 28;
const FONT_FAMILY = "Arial, Helvetica, sans-serif";
const clamp = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

interface TextLayerProps {
  text: string;
  fontSize: number;
  fontWeight: number;
  gradientStart: string;
  gradientEnd: string;
  ghostColor: string;
  maskImage: string;
}

function TextLayer({
  text,
  fontSize,
  fontWeight,
  gradientStart,
  gradientEnd,
  ghostColor,
  maskImage,
}: TextLayerProps) {
  const textStyle = {
    display: "block",
    fontFamily: FONT_FAMILY,
    fontSize,
    fontWeight,
    letterSpacing: 0,
    lineHeight: 0.88,
    whiteSpace: "nowrap" as const,
  };

  return (
    <div style={{ position: "relative" }}>
      <span style={{ ...textStyle, color: ghostColor }}>{text}</span>
      <span
        style={{
          ...textStyle,
          position: "absolute",
          inset: 0,
          color: "transparent",
          backgroundImage: `linear-gradient(90deg, ${gradientStart} 0%, ${gradientStart} 4%, ${gradientEnd} 26%, ${gradientEnd} 100%)`,
          backgroundClip: "text",
          maskImage,
          maskRepeat: "no-repeat",
          opacity: 1,
          WebkitBackgroundClip: "text",
          WebkitMaskImage: maskImage,
          WebkitMaskRepeat: "no-repeat",
        }}
      >
        {text}
      </span>
    </div>
  );
}

function GradientScaleCutTextBase({
  text = "Introducing",
  giantFontSize = 520,
  compactFontSize = 132,
  fontWeight = 700,
  gradientStart = "#f04a14",
  gradientEnd = "#f3f1f1",
  ghostColor = "#170b0a",
  backgroundColor = "#000000",
  anchorOffsetX = -16,
  giantTravel = 400,
  settleTravel = 160,
  cutFrame = 13,
  revealSoftness = 14,
  compactBlur = 12,
  speed = 1,
  className,
}: GradientScaleCutTextProps) {
  const frame = useCurrentFrame() * Math.max(speed, 0);
  const safeCutFrame = Math.max(cutFrame, 1);
  const safeGiantFontSize = Math.max(giantFontSize, 1);
  const safeCompactFontSize = Math.max(compactFontSize, 1);
  const safeSoftness = Math.max(revealSoftness, 0);
  const safeBlur = Math.max(compactBlur, 0);
  const revealProgress = interpolate(frame, [0, REVEAL_END], [0.02, 1], {
    ...clamp,
    easing: Easing.bezier(0.22, 0.74, 0.24, 1),
  });
  const revealEdge = revealProgress * 100;
  const revealSolid = Math.max(0, revealEdge - safeSoftness / 2);
  const revealFade = Math.min(100, revealEdge + safeSoftness / 2);
  const maskImage = `linear-gradient(90deg, #000 0%, #000 ${revealSolid}%, transparent ${revealFade}%, transparent 100%)`;
  const giantProgress = interpolate(
    frame,
    [0, Math.max(safeCutFrame - 1, 1)],
    [0, 1],
    {
      ...clamp,
      easing: Easing.out(Easing.cubic),
    },
  );
  const settleProgress = interpolate(
    frame,
    [safeCutFrame, safeCutFrame + SETTLE_FRAMES],
    [0, 1],
    {
      ...clamp,
      easing: Easing.out(Easing.cubic),
    },
  );
  const resolveProgress = interpolate(
    frame,
    [safeCutFrame + SETTLE_FRAMES, REVEAL_END],
    [0, 1],
    {
      ...clamp,
      easing: Easing.inOut(Easing.cubic),
    },
  );
  const moveProgress = interpolate(
    frame,
    [
      safeCutFrame + 1,
      safeCutFrame + 2,
      safeCutFrame + 4,
      safeCutFrame + SETTLE_FRAMES,
    ],
    [0, 0.58, 0.875, 1],
    clamp,
  );
  const showGiant = frame < safeCutFrame;
  const isResolving = frame > safeCutFrame + SETTLE_FRAMES;
  const compactX = isResolving
    ? interpolate(resolveProgress, [0, 1], [COMPACT_MID_X, 0], clamp)
    : interpolate(moveProgress, [0, 1], [settleTravel, COMPACT_MID_X], clamp) +
      COMPACT_START_X_CORRECTION * (1 - moveProgress);
  const compactBlurValue = safeBlur * (1 - settleProgress);

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        overflow: "hidden",
        backgroundColor,
      }}
    >
      {showGiant ? (
        <div
          style={{
            position: "absolute",
            top: `calc(50% + ${GIANT_Y}px)`,
            left: `calc(50% + ${anchorOffsetX + GIANT_X_CORRECTION - giantTravel * giantProgress}px)`,
            opacity: 1,
            transform: "translate3d(0, -50%, 0)",
          }}
        >
          <TextLayer
            text={text}
            fontSize={safeGiantFontSize}
            fontWeight={fontWeight}
            gradientStart={gradientStart}
            gradientEnd={gradientEnd}
            ghostColor={ghostColor}
            maskImage={maskImage}
          />
        </div>
      ) : (
        <div
          style={{
            position: "absolute",
            top: `calc(50% + ${COMPACT_Y}px)`,
            left: `calc(50% + ${anchorOffsetX + compactX}px)`,
            filter: `blur(${compactBlurValue}px)`,
            opacity: 1,
            transform: `translate3d(-50%, -50%, 0) scaleX(${COMPACT_X_SCALE})`,
            transformOrigin: "center",
          }}
        >
          <TextLayer
            text={text}
            fontSize={safeCompactFontSize}
            fontWeight={fontWeight}
            gradientStart={gradientStart}
            gradientEnd={gradientEnd}
            ghostColor={ghostColor}
            maskImage={maskImage}
          />
        </div>
      )}
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  text: {
    type: "text-content",
    default: "Introducing",
    description: "Text",
  },
  giantFontSize: {
    type: "number",
    min: 160,
    max: 720,
    step: 4,
    default: 520,
    description: "Giant font size",
    hiddenFromList: false,
  },
  compactFontSize: {
    type: "number",
    min: 40,
    max: 240,
    step: 2,
    default: 132,
    description: "Compact font size",
    hiddenFromList: false,
  },
  anchorOffsetX: {
    type: "number",
    min: -400,
    max: 400,
    step: 4,
    default: -16,
    description: "Final horizontal anchor offset",
    hiddenFromList: false,
  },
  giantTravel: {
    type: "number",
    min: 0,
    max: 800,
    step: 4,
    default: 400,
    description: "Giant phase left travel",
    hiddenFromList: false,
  },
  settleTravel: {
    type: "number",
    min: 0,
    max: 400,
    step: 4,
    default: 160,
    description: "Compact phase left travel",
    hiddenFromList: false,
  },
  cutFrame: {
    type: "number",
    min: 4,
    max: 24,
    step: 1,
    default: 13,
    description: "Hard cut frame",
    hiddenFromList: false,
  },
  revealSoftness: {
    type: "number",
    min: 0,
    max: 40,
    step: 1,
    default: 14,
    description: "Reveal edge softness",
    hiddenFromList: false,
  },
  compactBlur: {
    type: "number",
    min: 0,
    max: 40,
    step: 1,
    default: 12,
    description: "Blur after the cut",
    hiddenFromList: false,
  },
  gradientStart: {
    type: "color",
    default: "#f04a14",
    description: "Gradient start",
  },
  gradientEnd: {
    type: "color",
    default: "#f3f1f1",
    description: "Gradient end",
  },
  ghostColor: {
    type: "color",
    default: "#170b0a",
    description: "Unrevealed text color",
  },
  backgroundColor: {
    type: "color",
    default: "#000000",
    description: "Background color",
  },
  fontWeight: {
    type: "enum",
    default: "700",
    variants: {
      "400": {},
      "500": {},
      "600": {},
      "700": {},
    },
    description: "Font weight",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["text","giantFontSize","compactFontSize","anchorOffsetX","giantTravel","settleTravel","cutFrame","revealSoftness","compactBlur","gradientStart","gradientEnd","ghostColor","backgroundColor","fontWeight","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  text: "Introducing",
  giantFontSize: 520,
  compactFontSize: 132,
  anchorOffsetX: -16,
  giantTravel: 400,
  settleTravel: 160,
  cutFrame: 13,
  revealSoftness: 14,
  compactBlur: 12,
  gradientStart: "#f04a14",
  gradientEnd: "#f3f1f1",
  ghostColor: "#170b0a",
  backgroundColor: "#000000",
  fontWeight: "700",
  speed: 1,
};

type GradientScaleCutTextElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof GradientScaleCutTextBase>;

const GradientScaleCutTextInner = forwardRef<
  HTMLDivElement,
  GradientScaleCutTextElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<GradientScaleCutText>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <GradientScaleCutTextBase
          {...(componentProps as unknown as ComponentProps<typeof GradientScaleCutTextBase>)}
        />
      </div>
    </Sequence>
  );
});

export const GradientScaleCutText = Interactive.withSchema({
  Component: GradientScaleCutTextInner,
  componentName: "<GradientScaleCutText>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
